import { useState } from 'react';

export default function {{component_name}}({ min = 0, max = 100 }: { min?: number; max?: number }) {
  const [lo, setLo] = useState(min);
  const [hi, setHi] = useState(max);
  return (
    <div>
      <input type="range" min={min} max={max} value={lo} onChange={(e) => setLo(Math.min(Number(e.target.value), hi))} className="w-full" />
      <input type="range" min={min} max={max} value={hi} onChange={(e) => setHi(Math.max(Number(e.target.value), lo))} className="w-full" />
      <div className="text-sm">{lo} - {hi}</div>
    </div>
  );
}
